  <link rel="stylesheet" href="styles.css">
  <script src="script.js" defer></script>
</head>
<body>
  <main class="app-shell">
    <header class="hero">
      <div class="brand-mark" aria-hidden="true">✦</div>
      <div>
        <p class="eyebrow">PERSONAL SCHEDULER</p>
        <h1>Appointment booking</h1>
        <p class="subtitle">Plan your next conversation, consultation, or check-in.</p>
      </div>
    </header>

    <section class="content-grid">
      <section class="panel form-panel" aria-labelledby="form-title">
        <div class="section-heading">
          <div>
            <p class="eyebrow accent">NEW APPOINTMENT</p>
            <h2 id="form-title">Reserve a time</h2>
          </div>
          <span class="step-badge">01</span>
        </div>
        <form id="booking-form" novalidate>
          <div class="field">
            <label for="booking-name">Customer name</label>
            <input id="booking-name" data-testid="booking-name" name="name" type="text" placeholder="e.g. Jordan Lee" required autocomplete="name">
          </div>
          <div class="field">
            <label for="booking-email">Email address</label>
            <input id="booking-email" data-testid="booking-email" name="email" type="email" placeholder="you@example.com" required autocomplete="email">
          </div>
          <div class="two-column">
            <div class="field">
              <label for="booking-date">Appointment date</label>
              <input id="booking-date" data-testid="booking-date" name="date" type="date" required>
            </div>
            <div class="field">
              <label for="booking-time">Appointment time</label>
              <input id="booking-time" data-testid="booking-time" name="time" type="time" required>
            </div>
          </div>
          <div class="field">
            <label for="booking-type">Appointment type</label>
            <select id="booking-type" data-testid="booking-type" name="type" required>
              <option value="">Choose a type</option>
              <option>Discovery call</option>
              <option>Consultation</option>
              <option>Follow-up</option>
              <option>Routine check-in</option>
            </select>
          </div>
          <p class="form-error" id="form-error" role="alert" aria-live="polite"></p>
          <button class="primary-button" data-testid="booking-submit" type="submit">Create booking <span aria-hidden="true">→</span></button>
        </form>
      </section>

      <section class="panel bookings-panel" aria-labelledby="bookings-title">
        <div class="section-heading bookings-heading">
          <div>
            <p class="eyebrow accent">YOUR SCHEDULE</p>
            <h2 id="bookings-title">Upcoming bookings</h2>
          </div>
          <span class="count" id="booking-count">0</span>
        </div>
        <div id="booking-confirmation" data-testid="booking-confirmation" class="confirmation" role="status" aria-live="polite" hidden></div>
        <div id="booking-list" data-testid="booking-list" class="booking-list">
          <div class="empty-state" id="empty-state">
