const form = document.getElementById('booking-form');
const list = document.getElementById('booking-list');
const emptyState = document.getElementById('empty-state');
const error = document.getElementById('form-error');
const confirmation = document.getElementById('booking-confirmation');
const count = document.getElementById('booking-count');
const dateInput = document.getElementById('booking-date');
let bookings = [];

const today = new Date();
const localToday = new Date(today.getTime() - today.getTimezoneOffset() * 60000).toISOString().split('T')[0];
dateInput.min = localToday;

function showError(message) {
  error.textContent = message;
  confirmation.hidden = true;
}

function render() {
  list.querySelectorAll('[data-testid="booking"]').forEach(card => card.remove());
  emptyState.hidden = bookings.length > 0;
  count.textContent = bookings.filter(item => !item.cancelled).length;
  bookings.forEach(item => {
    const card = document.createElement('article');
    card.className = 'booking-card' + (item.cancelled ? ' cancelled' : '');
    card.dataset.testid = 'booking';
    card.dataset.status = item.cancelled ? 'cancelled' : 'active';
    const date = new Date(item.date + 'T00:00:00');
    const dateText = date.toLocaleDateString(undefined, { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric' });
    const timeText = new Date('1970-01-01T' + item.time).toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' });
    card.innerHTML = `<div class="booking-top"><div><h3 class="booking-name" data-testid="booking-name-display"></h3><p class="booking-type"></p></div><span class="status-label">${item.cancelled ? 'Cancelled' : 'Confirmed'}</span></div><p class="date-line">${dateText} · ${timeText}</p>${item.cancelled ? '' : '<button class="cancel-button" data-testid="booking-cancel" type="button">Cancel appointment</button>'}`;
    card.querySelector('.booking-name').textContent = item.name;
    card.querySelector('.booking-type').textContent = item.type;
    if (!item.cancelled) card.querySelector('.cancel-button').addEventListener('click', () => { item.cancelled = true; render(); });
    list.appendChild(card);
  });
}

form.addEventListener('submit', event => {
  event.preventDefault();
  error.textContent = '';
  if (!form.checkValidity()) { form.reportValidity(); return; }
  const data = new FormData(form);
  if (data.get('date') < localToday) { showError('Please choose today or a future date.'); return; }
  const booking = { name: data.get('name').trim(), email: data.get('email').trim(), date: data.get('date'), time: data.get('time'), type: data.get('type'), cancelled: false };
  if (!booking.name) { showError('Please enter a customer name.'); return; }
  bookings.push(booking);
  render();
  form.reset();
  dateInput.min = localToday;
  confirmation.textContent = `Booking confirmed for ${booking.name}.`;
  confirmation.hidden = false;
  confirmation.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
});

render();

